// Express-style middleware for an RBAC permission check
const ROLE_PERMISSIONS = {
  admin: ['create_task', 'edit_task', 'delete_task', 'invite_member', 'remove_member', 'delete_project'],
  editor: ['create_task', 'edit_task', 'comment_task'],
  viewer: ['view_task', 'comment_task'],
};

function getPermissionsForRoles(roles) {
  const perms = new Set();
  for (const role of roles) {
    for (const perm of ROLE_PERMISSIONS[role] || []) {
      perms.add(perm);
    }
  }
  return perms;
}

function requirePermission(permission) {
  return (req, res, next) => {
    // req.user.roles comes from your auth layer, e.g. ['editor']
    const granted = getPermissionsForRoles(req.user.roles);
    if (!granted.has(permission)) {
      return res.status(403).json({ error: 'forbidden' });
    }
    next();
  };
}

// Usage on a route
app.delete('/tasks/:id', requirePermission('delete_task'), deleteTaskHandler);

